Sure! Here's a simple JavaScript function that takes a string as input and returns a new string with the order of adjectives reversed:

```javascript
function reverseAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(" ");

  // Find all the adjective indices (words starting with 'a-z' and not hyphenated)
  const adjectiveIndices = [];
  for (let I = 0; I < words.length; i++) {
    const firstLetter = words[i][0];
    const hasHyphen = words[i].includes("-");
    if (/[a-z]/.test(firstLetter) && !hasHyphen) {
      adjectiveIndices.push(i);
    }
  }

  // Reverse the order of adjectives and concatenate the result with the remaining words
  const reversedAdjectives = adjectiveIndices.slice().reverse().map((index) => words[index]).join(" ");
  const nonAdjectiveWords = words.slice(0, Math.min(adjectiveIndices[0], words.length - 1))
                       .concat(words.slice(Math.max(adjectiveIndices[adjectiveIndices.length - 1] + 1), words.length)).join(" ");
  return `${reversedAdjectives} ${nonAdjectiveWords}`;
}
```

