const cheerio = require('cheerio'); // Required library for parsing HTML/XML documents
const config = require('./config'); // Configuration file containing Slack API credentials

function sendMessage(text, channel) {
  const webhookUrl = config.slackWebhookUrl; // Retrieve the Slack Webhook URL from configuration file
  const data = {
    text: text, // Message text
    channel: channel, // Channel where message will be posted
    username: 'Slackbot', // Name of bot sending message
