```cpp
#include <iostream>
#include <iomanip>

int main() {
    const double PURCHASE_PRICE = 1000;
    const double RESIDUAL_VALUE = 200;
    const double REFUND = 600;

    // Calculate the refund decimal
    double refundDecimal = (REFUND - RESIDUAL_VALUE) / PURCHASE_PRICE;

    // Calculate the percentage of refund
    double percentageOfRefund = refundDecimal * 100;

    std::cout << "The refund is " << std::fixed << std::setprecision(2) << percentageOfRefund << "% (" << REFUND << ") of the original price (" << PURCHASE_PRICE << ") after deducting the residual value (" << RESIDUAL_VALUE << ")." << std::endl;

    return 0;
}
```

