    var result = ""
    let words = text.components(separatedBy: .whitespacesAndNewlines)
    for word in words {
        let lowercasedWord = word.lowercased()
        for (homophone, replacement) in homophones {
            let range = lowercasedWord.range(of: homophone, options: .caseInsensitive)
            if let range = range {
                result += String(word[..<range.lowerBound]) + String(replacement[lowercasedWord[range.upperBound...].firstIndex(of: homophone[homophone.startIndex])!]) + String(word[range.upperBound..<word.endIndex])
                break
            }
        }
        result += String(word)
    }
    return result
}

