function searchPlace(placeName) {
  // Define API key and URL for Google Maps Geocoding API
  const apiKey = "YOUR_API_KEY";
  const url = "https://maps.googleapis.com/maps/api/geocode/json";

  // Make a GET request to the API with the place name
  const response = UrlFetchApp.fetch(`${url}?key=${apiKey}&address=${placeName}`);
